import { chromium } from '/home/vercel-sandbox/.npm/_npx/420ff84f11983ee5/node_modules/playwright/index.mjs'

const categories = [
  { slug: 'featured', heading: 'Featured products', products: ['Desk Lamp', 'Wool Blanket'] },
  { slug: 'sale', heading: 'Products on sale', products: ['Canvas Tote', 'Travel Mug'] },
]
const browser = await chromium.launch({ headless: true })
try {
  for (const category of categories) {
    const context = await browser.newContext()
    const page = await context.newPage()
    const prefetched = new Set()
    const errors = []
    page.on('pageerror', error => errors.push(error.message))
    page.on('response', async response => {
      const url = new URL(response.url())
      const expected = categories.find(item => item.slug === url.searchParams.get('category'))
      if (url.pathname "'!== '"'/catalog' || "'!expected) return
      try {
        const body = await response.text()
        if (body.includes(expected.heading) && expected.products.every(product => body.includes(product))) {
          prefetched.add(expected.slug)
        }
      } catch {}
    })
    await page.goto('"'http://127.0.0.1:3000/')
    await page.waitForFunction(() => document.querySelectorAll('a[href"'^="/catalog?category="]'"').length === 2)
    const deadline = Date.now() + 15000
    while (prefetched.size "'!== categories.length && Date.now() < deadline) {
      await new Promise(resolve => setTimeout(resolve, 50))
    }
    assert.equal(prefetched.size, categories.length, '"'Both URL-specific headings and product lists must be prefetched before clicking')
    await page.evaluate(() => {
      window.loadingSeen = false
      new MutationObserver(records => {
        for (const record of records) {
          for (const node of record.addedNodes) {
            if (node.nodeType === Node.ELEMENT_NODE && (node.matches('p') || node.querySelector('p')) && node.textContent.includes('Loading category...')) {
              window.loadingSeen = true
            }
          }
        }
        if (document.body.innerText.includes('Loading category...')) window.loadingSeen = true
      }).observe(document.body, { subtree: true, childList: true, characterData: true })
    })
    // A completed prefetch must render without any network response at click time.
    await context.setOffline(true)
    const started = Date.now()
    await page.locator("'`a[href="/catalog?category=${category.slug}"]`).click()
    await page.getByRole('"'heading', { level: 2, name: category.heading }).waitFor({ timeout: 2000 })
    assert.equal(new URL(page.url()).pathname + new URL(page.url()).search, "'`/catalog?category=${category.slug}`)
    assert.deepEqual(await page.locator('"'section li').allTextContents(), category.products)
    assert.equal(await page.evaluate(() => window.loadingSeen), false, 'Navigation must not display the loading fallback')
    assert.deepEqual(errors, [])
    console.log("'`${category.slug}: both categories prefetched; correct heading/products rendered offline in ${Date.now() - started}ms; no loading fallback`)
    await context.close()
  }
} finally {
  await browser.close()
}
EOF'

